package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_createContextual_TriageGen1Test {

    private StringArrayDeserializer deserializer;
    private DeserializationContext ctxt;
    private BeanProperty property;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
    }

    /**
     * Tests the case where the deserializer remains unchanged (no contextual changes).
     * This happens if findConvertingContentDeserializer returns the same instance,
     * and it's not a default deserializer.
     */
    @Test
    public void testCreateContextual_ReturnsSelf() throws JsonMappingException {
        // Mock behavior to simulate finding the same deserializer
        // We use a spy to control findConvertingContentDeserializer behavior if possible, 
        // but since it's protected, we rely on the internal field _elementDeserializer if we could set it.
        // Since we can't set private fields easily without reflection, we assume the default state.

        // In the default state, _elementDeserializer is likely null or a default.
        // If deser is null, it goes to findContextualValueDeserializer.

        JavaType stringType = mock(JavaType.class);
        when(ctxt.constructType(String.class)).thenReturn(stringType);

        // If findContextualValueDeserializer returns null, and isDefaultDeserializer is true, deser becomes null.
        // If deser is null, _elementDeserializer (null) == deser (null), returns this.
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(null);

        // To ensure isDefaultDeserializer(null) doesn't crash and returns true/false
        // Usually, if deser is null, the code reaches return this.

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);
        assertEquals(deserializer, result);
    }

    /**
     * Tests the case where a new StringArrayDeserializer is created because a new 
     * contextual deserializer was found.
     */
    @Test
    public void testCreateContextual_ReturnsNewDeserializer() throws JsonMappingException {
        // We need to bypass the "isDefaultDeserializer" check and the "deser == _elementDeserializer" check.
        // Since we can't easily set _elementDeserializer via public API, we simulate the flow.
        // We will use reflection to set the private field _elementDeserializer to a mock.

        try {
            JsonDeserializer<?> mockElementDeser = mock(JsonDeserializer.class);
            java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
            field.setAccessible(true);
            field.set(deserializer, mockElementDeser);

            JavaType stringType = mock(JavaType.class);
            when(ctxt.constructType(String.class)).thenReturn(stringType);

            // Simulate findConvertingContentDeserializer returning null (so it goes to findContextualValueDeserializer)
            // Or returning a different deserializer.
            JsonDeserializer<?> differentDeser = mock(JsonDeserializer.class);
            when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(differentDeser);

            // Ensure differentDeser is not considered a "default" deserializer
            // Since we can't easily mock isDefaultDeserializer (it's private/protected), 
            // we assume a mock object is not the default String deserializer.

            JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

            assertNotNull(result);
            assertNotSame(deserializer, result);
            assertTrue(result instanceof StringArrayDeserializer);
        } catch (Exception e) {
            fail("Reflection failed: " + e.getMessage());
        }
    }

    /**
     * Tests the branch where findConvertingContentDeserializer returns a non-null deserializer,
     * triggering handleSecondaryContextualization.
     */
    @Test
    public void testCreateContextual_HandleSecondaryContextualization() throws JsonMappingException {
        try {
            JsonDeserializer<?> mockElementDeser = mock(JsonDeserializer.class);
            java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
            field.setAccessible(true);
            field.set(deserializer, mockElementDeser);

            JsonDeserializer<?> secondaryDeser = mock(JsonDeserializer.class);
            when(ctxt.handleSecondaryContextualization(eq(mockElementDeser), eq(property))).thenReturn(secondaryDeser);

            // We need to make sure findConvertingContentDeserializer returns mockElementDeser.
            // Since it's a protected method in the same class, we can't easily mock it without a spy.
            StringArrayDeserializer spyDeserializer = Mockito.spy(deserializer);

            // Note: findConvertingContentDeserializer is protected. 
            // In a real scenario, we'd use a spy to return the mockElementDeser.
            doReturn(mockElementDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());

            JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

            assertNotNull(result);
            assertNotSame(spyDeserializer, result);
            verify(ctxt).handleSecondaryContextualization(mockElementDeser, property);
        } catch (Exception e) {
            fail("Test failed: " + e.getMessage());
        }
    }

    /**
     * Tests the branch where the found deserializer is a default deserializer,
     * resulting in deser becoming null.
     */
    @Test
    public void testCreateContextual_DefaultDeserializerBecomesNull() throws JsonMappingException {
        try {
            // We use a spy to control the flow
            StringArrayDeserializer spyDeserializer = Mockito.spy(deserializer);

            // Mock findConvertingContentDeserializer to return a deserializer
            JsonDeserializer<?> defaultDeser = mock(JsonDeserializer.class);
            doReturn(defaultDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());

            // We need to trick isDefaultDeserializer. 
            // Since we can't easily, we assume if it's a mock it might return false, 
            // unless we can mock the internal logic. 
            // However, if deser becomes null, the final check _elementDeserializer != deser 
            // will likely trigger a new StringArrayDeserializer(null).

            // Let's simulate the case where deser becomes null via the isDefaultDeserializer check.
            // This requires the spy to return true for isDefaultDeserializer.
            // But isDefaultDeserializer is not easily mockable if it's private.
            // If it's protected, we can. Let's assume we can mock it via spy.

            doReturn(true).when(spyDeserializer).isDefaultDeserializer(defaultDeser);

            // Setup _elementDeserializer to be something else so that _elementDeserializer != null
            java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
            field.setAccessible(true);
            field.set(spyDeserializer, mock(JsonDeserializer.class));

            JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

            assertNotNull(result);
            assertTrue(result instanceof StringArrayDeserializer);
        } catch (Exception e) {
            fail("Test failed: " + e.getMessage());
        }
    }
}
